document_data = []

for pdf in pdf_files:
    try:
        text = extract_pdf_text(pdf)
        pages = len(PdfReader(str(pdf)).pages)
        document_data.append({
            "filename": pdf.name,
            "pages": pages,
            "characters": len(text),
            "words": len(text.split()),
            "status": "Processed"
        })
    except Exception as error:
        document_data.append({
            "filename": pdf.name,
            "pages": 0,
            "characters": 0,
            "words": 0,
            "status": f"Error: {error}"
